<section id="faq-section" class="content-section" style="background-color: #ffffff;">
    <div class="content-container">
        <div class="text-content">
            <div class="faq-expanded">
                <aside class="faq-expanded__aside">
                    <h2 class="faq-expanded__title">FAQs - Change in Authorised Capital in Gurugram</h2>
                    <p class="faq-expanded__lead">Common questions about authorised capital changes, Form SH-7, Haryana stamp duty, and ROC filing for Gurugram companies.</p>
                    @include('partials.bigin-form', [
                        'variant'  => 'compact',
